#!/usr/bin/env bash
# Docs : partie « Configuration » (chapitres package.json et monorepo, TypeScript et tsconfig),
# correction du chapitre lint (le React Compiler n'est pas activé, seules ses règles sont vérifiées).
# Prérequis : apply-docs-selecteur-systeme.sh.
# Usage (racine du repo) : bash apply-docs-configuration-1.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" 2>/dev/null | grep -qF "Partie suivante : la configuration"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "function OsSelect" "apps/web/src/features/docs/ui/OsSelect.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-selecteur-systeme.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" "apps/web/src/features/docs/lib/docs.navigation.ts")
CREATED=("apps/web/content/docs/dev/configuration/package-json-et-monorepo.mdx" "apps/web/content/docs/dev/configuration/typescript-et-tsconfig.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/configuration" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "Partie suivante : la configuration" "apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/configuration"
