python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
sub('apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx', '',
    '')
sub('apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx', '',
    '')
sub('apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx', '',
    '')
sub('apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx', '',
    '')
sub('apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx', '',
    '')
sub('apps/web/src/features/docs/lib/docs.navigation.ts', 'ICAiQWNjdWVpbCIsCiAgIkTDqW1hcnJlciIsCiAgIkZvbmRhdGlvbnMgZnJvbnQiLAogICJEb25uw6llcyIsCg==',
    'ICAiQWNjdWVpbCIsCiAgIkTDqW1hcnJlciIsCiAgIkNvbmZpZ3VyYXRpb24iLAogICJGb25kYXRpb25zIGZyb250IiwKICAiRG9ubsOpZXMiLAo=')
print("  édits ok (6 substitutions, 2 fichiers créés, 0 remplacés)")
